import json,pathlib
R=[]
def add(file,method,observation,application,limits,start=None):
 d=dict(repo='baileyholl/Ars-Nouveau',file='/'+file+'.java',method=method,observation=observation,application=application,limits=limits)
 if start:d['start']=start
 R.append(d)
add('ISummon','writeOwner','仅在owner UUID非空时写入owner键；保存归属不依赖实体指针仍存在。','租约元数据应保存稳定UUID，目标筛选再独立解析在线owner。','这是所有权持久化，不等于选敌过滤；不能只因存在UUID就允许攻击。')
add('ISummon','readOwner','检测owner键后在指定ServerLevel按UUID查实体，缺键返回null。','离线、跨维度或未加载owner必须有明确失败分支，不能继承野生攻击行为。','世界级查找不保证跨维度命中；研究针对此固定NeoForge版本源码。')
add('IFamiliar','onFamiliarSpawned','当事件owner等于本魔宠owner且新实体不是自身时丢弃旧实体，按owner限制存量。','重复穿戴召唤应按owner和generation管理，另一玩家召唤不能清除本人的护卫。','这里按对象相等且未见null保护；不可直接当作本项目跨死亡或重登方案。')
add('IFamiliar','getOwner','先排除客户端和空ownerID，再在ServerLevel按UUID查找并转为LivingEntity。','服务端权威owner解析要明确客户端与无owner边界，避免把解析失败当野生。','强制LivingEntity转换假定UUID对应生物；不提供任何Enemy判定。')
add('SummonUtil','canSummonTakeDamage','仅允许绕过无敌的伤害或来源实体为Player的伤害进入。','输入受伤白名单和输出攻击白名单是独立边界，护卫修复须查输出目标。','该策略会允许任意玩家伤害且不含盟友过滤，不适合直接照搬本项目。')
add('SummonWolf','tick','先执行Wolf原生tick，服务端递减ticksLeft；到期播放粒子并discard，再发didExpire死亡事件。','租约到期应真正移除实体；也提醒super.tick前后顺序影响到期当帧是否还能攻击。','本方法自身未过滤原生Wolf目标；不能作为旁观玩家安全证明。')
add('SummonWolf','readAdditionalSaveData','调用父类恢复后读取left寿命和wildenSummon标记。','存档载入不能默认重新发满租约寿命；要保留原已消耗时间。','这里只是剩余tick型保存，非绝对deadline；离线时间语义不同。')
add('SummonWolf','addAdditionalSaveData','调用父类保存后写left和wildenSummon，保持召唤状态可重建。','检查父类归属保存与子类租约字段的组合，不能仅看一层NBT。','与读取为互补独立写入边界，不代表父类所有字段已经人工审查。')
add('SummonSkeleton','registerGoals','以跟随替代漫游并保留受伤反击；匿名反击canAttack排除owner UUID。另优先CopyOwnerTarget，最近Mob仅选正在攻击owner或killCredit为owner者。','全目标入口都需受保护，包括继承目标、反击和复制owner目标；只定时重选不够。','此策略允许保护主人产生的战斗目标，本项目已定Enemy-only，不能增加其更宽的报复规则。')
add('SummonSkeleton','reassessWeaponGoal','仅服务端且主手非EMPTY时先移除两种战斗goal，按弓或其他武器重挂一种，避免重复挂载。','验证换装不会叠加战斗goal；清目标与切战斗方式是不同操作。','此处不是所有权检查；空手分支没有移除旧goal，需按上下文看待。')
add('SummonSkeleton','hurt','只对MOB_ATTACK且来源ISummon时比较双方ownerUUID；同owner直接拒伤，其他情况交父类。','同owner友伤拦截是最后一道防线，必须同时修目标获取和持续阶段。','仅覆盖一种伤害类型，投射物、其他类型和非同owner旁观者不在保护范围。')
add('SummonSkeleton','tick','每tick先父类逻辑，再递减limitedLifeTicks；归零后设20并以starve20伤害收尾。','到期伤害式清理和直接discard不同，需实测无敌或减伤是否阻止清理。','这里没有检查limitedLifespan，且不是本项目租约策略；只记录实际控制流。')
add('SummonSkeleton','getTeam','实时可解析summoner时返回其team，否则回退父类team。','owner换队后应重新评估目标；仅召唤时复制team可能过时。','队伍关系无法表达所有非Enemy旁观者，因此不是本项目完整目标许可。')
add('SummonSkeleton','isAlliedTo','owner存在时同owner的ISummon直接结盟；否则owner本人或owner.isAlliedTo为盟友，解析失败回退父类。','明确同owner召唤物、owner与其盟友三类；Enemy白名单仍需独立保证。','离线owner回退原生行为有风险；不能把未结盟等同于可攻击。')
add('SummonSkeleton','readAdditionalSaveData','恢复Bound坐标、可选LifeTicks，并优先OwnerUUID否则旧名转换；非空UUID经try调用setOwnerID。','核对旧档转换失败时不能变为野生敌对；metadata读取必须和租约标记一致。','这份代码以类型8判断OwnerUUID，具体NBT版本兼容需另核，不能宣称所有版本正常。')
add('SummonSkeleton','getOwnerFromID','取得同步UUID后用当前level.getPlayerByUUID解析，空UUID或IllegalArgumentException返回null。','owner解析是玩家限定且世界限定；空结果应保留租约保护标记。','EntityAllyVex存在相同实现，不再重复计数；此方法不支持非玩家召唤者。')
add('SummonSkeleton','addAdditionalSaveData','可选保存Bound坐标；仅limitedLifespan为真保存LifeTicks；owner空则保存NIL_UUID。','区分缺字段与哨兵UUID，避免重载把临时召唤变长期实体。','EntityAllyVex写法近似不再计数；读写条件不对称需注意，不直接采纳。')
add('EntityAllyVex','registerGoals','设置冲刺、跟随、CopyOwnerTarget和仅选攻击owner/owner killCredit的Mob目标，未注册泛Player最近目标。','从注册源头收窄召唤物目标，而非每20tick纠正已经攻击的对象。','仍须审计复制owner目标和攻击阶段；不能因不存在Player goal就直接证明Enemy-only。')
add('EntityAllyVex','canUse','冲刺开始要求有target、MoveControl空闲且随机1/7命中，最后距离平方大于4。','战斗动作开始阶段应检查当前目标仍被允许，不能只看非空与距离。','原实现无owner/Enemy重新校验，是用于指出边界缺口的反例。')
add('EntityAllyVex','canContinueToUse','持续冲刺只要求MoveControl有目的地、charging为真且target非空存活。','目标关系变化后要停止持续动作，存活判定不能代替目标授权。','未做盟友/owner/Enemy检验；本项目不能照抄这一持续条件。')
add('EntityAllyVex','start','读取当前target眼部位置设MoveControl目的地，设置charging并播放音效。','从目标选择到动作开始之间应再次核验，避免旧target已非法仍启动。','此完整方法假定target非空；未提供授权过滤或竞态保护。')
add('EntityAllyVex','tick','冲刺tick与target碰撞即直接doHurtTarget并取消charging；距离平方小于9则继续追其眼部位置。','攻击落点前需要最终Enemy与owner过滤，不能只修定时选敌。','这个方法本身无过滤；它展示现有target可以穿透到伤害调用。',189)
add('EntityAllyVex','isAlliedTo','getOwnerAlt非空时，只保护owner本人或owner判为盟友者，否则用父类联盟关系。','与Skeleton同owner召唤判定存在差异，检查归属时不能只见isAlliedTo就断言同逻辑。','ownerAlt返回缓存owner，与UUID动态解析不同；重载后缓存恢复需单独关注。')
add('EntityAllyVex','getTeam','使用ownerAlt取队伍；若无缓存owner则回父类，不采用getOwnerFromID。','同一实体不同API的owner来源要统一审查，避免UUID有值但team丢失。','相比Skeleton多层null检查只是形式差异，但缓存owner与动态owner语义不同。')
add('FollowSummonerGoal','canUse','无summoner、旁观玩家summoner或命令坐下的Tamable均不启动；其余仅当距离达到minDist启动。','无主人或坐下不能回落为野生战斗；跟随启动和目标授权需分别审计。','这是移动goal，旁观者过滤针对主人，不是攻击旁观玩家的保护。')
add('FollowSummonerGoal','canContinueToUse','持续跟随要求导航未完成、owner还存在、距离超过maxDist且未坐下。','持续阶段重新解析owner可及时停止失效关系；目标持续阶段也应有类似守卫。','此处没有owner存活或跨维度检查，不能直接充当完整租约校验。')
add('FollowSummonerGoal','start','启动时把重算路径计数归零，并保存旧WATER寻路代价后暂设为0。','临时行为修改应有配对恢复，便于验收卸装与窗口撤销。','只涉及寻路状态，不证明攻击目标安全；与stop共同看恢复是否发生。')
add('FollowSummonerGoal','stop','结束时停止navigator并恢复先前WATER路径代价。','退出召唤行为应撤销临时导航影响，而不仅清目标字段。','这是跟随goal生命周期清理，不能替代装备租约expiry删除。')
add('FollowSummonerGoal','tick','每tick无owner返回；坐下不移动；每10tick重寻路，失败且距离平方至少144时扫描owner周围外圈安全块并传送。','周期扫描用于寻路节流可以，授权失效不能同样容忍10或20tick攻击窗口。','传送/导航行为与选敌不同；没有建议为本项目增加传送机制。')
add('FollowSummonerGoal','canTeleportToBlock','检查脚下block允许该实体生成且上面两格为空，才准许传送候选点。','实体位置夹具与真实碰撞可达性分开记录，避免归属测试被堵路掩盖。','此项仅关联召唤物跟随安全；不计同类简单旋转/材质或模型重复样本。')
add('FamOwnerHurtTargetGoal','canUse','读取服务端owner，非LivingEntity立即拒绝；取owner上次主动伤害对象和时间戳，须新时间戳、canAttack且wantsToAttack同时成立。','主人战斗信息只能作为候选来源，必须再经本项目Enemy白名单。','复制主人攻击对象会放宽本项目政策，因此只学多重门控，不引入PVP。')
add('FamOwnerHurtTargetGoal','canAttack','null直接拒绝；用潜在目标UUID排除owner后交TargetGoal.canAttack。','低层过滤要保护owner，但还需拒绝所有非Enemy旁观者。','另一个HurtBy类相同过滤不再计数；未覆盖同owner宠物UUID。')
add('FamOwnerHurtTargetGoal','start','先将缓存ownerLastHurt写入mob.target，再重新取owner更新已处理时间戳，最后super.start。','缓存候选从canUse到start仍需有效；目标写入也是可审计的授权入口。','这份实现未再次wantsToAttack或ownerUUID过滤，作为状态转换风险参考。')
add('FamOwnerHurtByTargetGoal','canUse','owner被打路径用getLastHurtByMob及对应timestamp，要求新事件、canAttack、wantsToAttack；owner丢失直接false。','区分主人主动攻击与受伤反击两条来源，不能只过滤最近Player目标。','与主动攻击goal的结构相似但事件来源相反；本项目仍只准Enemy，不自动允许反击玩家。')
